# -*- coding: utf-8 -*-
# Histoires du soir — série 2 (histoires 11 à 20), avec des voyages en rêve vers les pays voisins
HISTOIRES = [
 {"id": "h011", "age": "7-9", "titre": "Mbote, Libreville !",
  "texte": "Cette nuit-là, Super Brazza rêva qu’il voyageait sur un bateau fait de nuages. Le bateau glissa jusqu’à Libreville, la grande ville du Gabon, au bord de l’océan Atlantique. Le Gabon est un pays voisin du Congo, à l’ouest. Sur la plage, une petite fille nommée Léa construisait un château de sable. « Bonjour ! » dit-elle. « Mbote ! » répondit Super Brazza. Ils éclatèrent de rire : deux mots différents pour dire la même chose ! Léa lui apprit un jeu de coquillages. Super Brazza lui apprit à compter en lingala : moko, mibale, misato. Quand le soleil se coucha, Léa dit « Merci ! » et Super Brazza répondit « Matondi ! » Les pays voisins sont comme des cousins : on a toujours quelque chose à partager. Super Brazza se réveilla avec le sourire.",
  "morale": "Les voisins sont comme des cousins."},
 {"id": "h012", "age": "7-9", "titre": "Le bateau des rêves",
  "texte": "Un soir, depuis la rive de Brazzaville, Super Brazza regardait les lumières de l’autre côté du fleuve Congo. C’était Kinshasa, la grande ville du pays voisin, la République démocratique du Congo. « Qui vit là-bas ? » se demanda-t-il. Dans son rêve, un petit bateau de papier l’emmena sur l’eau. De l’autre côté, il rencontra Lola, une jeune bonobo très gentille. Les bonobos ne vivent que dans ce pays-là. Lola lui offrit un fruit sucré, et Super Brazza partagea sa banane. Ils jouèrent ensemble jusqu’à la nuit. « Nous sommes de chaque côté du même fleuve, dit Lola. — Alors nous sommes des frères », répondit Super Brazza. Il se réveilla avec le cœur tout chaud.",
  "morale": "Un fleuve peut séparer deux rives, mais pas deux amis."},
 {"id": "h013", "age": "4-6", "titre": "L’okapi timide",
  "texte": "Dans une grande forêt, de l’autre côté du fleuve, vivait un okapi très timide. Il avait des rayures noires et blanches sur les pattes, et c’est un cousin de la girafe. Quand quelqu’un s’approchait, il se cachait derrière les arbres. Super Brazza voulait devenir son ami, mais chaque fois que l’okapi le voyait, il disparaissait. Alors Super Brazza s’assit par terre, sans bouger, sans bruit. Il attendit longtemps. Doucement, l’okapi sortit un bout de son museau. Puis ses oreilles. Puis ses grands yeux doux. « Mbote », chuchota Super Brazza. L’okapi sourit. Ils restèrent côte à côte, en silence, très heureux. Parfois, pour se faire un ami, il suffit d’être patient et tranquille. Bonne nuit.",
  "morale": "Pour se faire un ami timide, il faut être patient."},
 {"id": "h014", "age": "7-9", "titre": "La goutte d’eau voyageuse",
  "texte": "Il était une fois une petite goutte d’eau nommée Mayi. Elle tomba un jour de pluie, tout près de Bangui, une ville au bord de la rivière Oubangui. Mayi glissa dans la rivière et se mit à voyager. « Où vais-je ? » se demanda-t-elle. L’Oubangui coula longtemps, longtemps, jusqu’à rejoindre le grand fleuve Congo. Mayi passa devant Brazzaville et ses bateaux. Elle continua, encore et encore, jusqu’à l’océan Atlantique. Là, le soleil la chauffa doucement, et Mayi monta dans le ciel, devenue un petit nuage. Un jour, elle retomberait en pluie, peut-être sur ton village. Dans la nature, rien ne se perd : l’eau voyage toujours. Bonne nuit, petite goutte.",
  "morale": "Dans la nature, rien ne se perd : l’eau voyage toujours."},
 {"id": "h015", "age": "7-9", "titre": "Le match de l’amitié",
  "texte": "Un jour, les Diables Rouges du Congo invitèrent les Lions Indomptables du Cameroun pour un match amical. Dans le stade, tout le monde chantait. Au début, les joueurs se regardaient de travers : chacun voulait gagner. Mais Super Brazza, qui jouait avec les Diables Rouges, vit un lion tomber. Sans réfléchir, il courut l’aider à se relever. « Merci, mon ami », dit le joueur camerounais. Ce geste changea tout. Les joueurs se mirent à sourire, à jouer avec plaisir et à se féliciter. Quand l’arbitre siffla la fin, personne n’était triste. Les deux équipes partagèrent un grand repas. Au fond, ce que l’on gagne dans un match, c’est surtout de nouveaux amis. Bonne nuit, petit joueur.",
  "morale": "Ce que l’on gagne dans un match, ce sont surtout des amis."},
 {"id": "h016", "age": "4-6", "titre": "La plus belle plume",
  "texte": "Un petit oiseau, ndeke en lingala, trouvait ses plumes toutes grises. « Je voudrais des plumes rouges, comme le perroquet ! » soupirait-il. Super Brazza l’entendit. « Ferme les yeux, petit ndeke, et écoute. » L’oiseau écouta : les oiseaux de la forêt chantaient tous une chanson différente. Alors il ouvrit son bec et chanta. Sa voix était si douce que les animaux s’arrêtèrent pour l’écouter. « Tu es le plus beau chanteur de la forêt ! » dit Mama Nzoku. Le petit oiseau comprit que sa vraie beauté n’était pas dans ses plumes, mais dans sa voix. Chacun a un trésor à découvrir. Ce soir-là, il s’endormit en chantant doucement.",
  "morale": "Chacun a un trésor à découvrir en lui."},
 {"id": "h017", "age": "7-9", "titre": "Les crayons de Grâce",
  "texte": "À l’école de Grâce, un matin, tout le monde dessinait. Mais Grâce n’avait plus de crayon : le sien s’était cassé. Elle était triste. Son voisin, Prince, en avait trois. Il hésita. « Si je prête mon crayon, il va peut-être se casser aussi », pensa-t-il. Puis il se souvint de ce que disait Super Brazza : « Ce que l’on partage devient plus grand. » Il tendit un crayon à Grâce. « Tiens, on dessinera ensemble. » Ils dessinèrent le fleuve Congo, avec un grand soleil jaune. Tous les enfants admirèrent leur dessin. Le soir, Prince était content : un crayon prêté lui avait donné une amie. Partager, c’est donner et recevoir en même temps.",
  "morale": "Ce que l’on partage devient plus grand."},
 {"id": "h018", "age": "7-9", "titre": "Le fleuve propre",
  "texte": "Super Brazza se promenait sur la berge du fleuve Congo quand il vit des sacs plastiques coincés dans les roseaux. « Oh non, mayi n’est plus propre ! » dit-il. Un petit poisson lui murmura : « J’ai du mal à respirer. » Super Brazza appela ses amis. Papa Gorille ramassa les grands sacs, Mama Nzoku les emporta avec sa trompe, et les enfants du quartier arrivèrent avec des paniers. En une heure, la berge était propre. Le soleil faisait briller l’eau claire. Le petit poisson fit un grand saut de joie. « Matondi ! » cria-t-il. Super Brazza dit aux enfants : « Ne jetez jamais vos déchets dans l’eau. C’est la maison des poissons. » Ce soir-là, tout le monde s’endormit fier d’avoir aidé la nature.",
  "morale": "Le fleuve est la maison des poissons : gardons-le propre."},
 {"id": "h019", "age": "4-6", "titre": "Le petit éléphant qui voulait voler",
  "texte": "Le petit de Mama Nzoku avait de grandes, grandes oreilles. « Avec mes oreilles, je peux voler ! » disait-il. Il courut très vite, battit des oreilles, sauta... et retomba dans la boue. « Aïe ! » Il était un peu triste. Super Brazza lui dit : « Les éléphants ne volent pas, mais tes oreilles ont un pouvoir magique. » Il lui montra comment les utiliser : elles rafraîchissent quand il fait chaud, comme un éventail. Le petit éléphant les agita doucement, et un petit vent frais caressa tout le monde. « Je suis le meilleur éventail de la forêt ! » rit-il. Il comprit que rêver est beau, mais que s’aimer tel qu’on est, c’est encore plus beau. Bonne nuit.",
  "morale": "S’aimer tel qu’on est, c’est magique."},
 {"id": "h020", "age": "10-12", "titre": "Un message pour Cabinda",
  "texte": "Super Brazza avait une correspondante qui vivait à Cabinda, une région d’Angola qui touche le sud du Congo. Elle s’appelait Luzia et elle parlait portugais. Un jour, il reçut sa lettre. Elle commençait par : « Bom dia ! », c’est-à-dire bonjour. Super Brazza voulut répondre dans sa langue à elle. Il chercha dans un dictionnaire, hésita, se trompa, recommença. Puis il écrivit : « Bom dia, Luzia ! Chez moi, on dit mbote. Je suis content d’être ton ami. » Quand Luzia reçut la lettre, elle sourit de bonheur. Apprendre quelques mots de la langue de l’autre, c’est lui dire : tu comptes pour moi. Les deux amis continuèrent à s’écrire, et chaque lettre leur apprenait un nouveau mot. Bonne nuit, petit voyageur des mots.",
  "morale": "Apprendre la langue de l’autre, c’est lui dire : tu comptes pour moi."},
]
